:is([data-slot="command-item"],[data-slot="menu-item"],[data-slot="select-item"],[data-slot="combobox-item"],[data-slot="autocomplete-item"],[data-slot="menu-radio-item"],[data-slot="menu-checkbox-item"],[data-slot="menu-sub-trigger"]){border-radius:2px !important}
:is([data-slot="command-item"],[data-slot="menu-item"],[data-slot="select-item"],[data-slot="combobox-item"],[data-slot="autocomplete-item"],[data-slot="menu-radio-item"],[data-slot="menu-checkbox-item"],[data-slot="menu-sub-trigger"]):is([data-highlighted],[data-selected]),[data-slot="command-item"][data-active]{background:color-mix(in srgb,var(--ac) 14%,#050911) !important;color:#fff !important;box-shadow:inset 2px 0 0 var(--ac) !important}
:is([data-slot="command-group-label"],[data-slot="menu-label"],[data-slot="select-group-label"]){color:var(--ac2) !important;font:600 11px/16px var(--hud-text) !important;letter-spacing:.12em !important;text-transform:uppercase !important}
[data-slot="command-footer"]{border-top:1px solid #16243a !important;background:#04070d !important}
:is([data-slot="kbd"],[data-slot="command-shortcut"] kbd){background:#0a0f18 !important;border:1px solid #233043 !important;border-radius:2px !important;color:#aab6c8 !important;box-shadow:none !important}
[data-slot="tooltip-popup"]{font-family:var(--sysfont);backdrop-filter:none !important;background:#050911 !important;border:1px solid var(--acb) !important;border-radius:2px !important;color:#dfe6f0 !important}
:is([data-slot="toast-popup"],[data-slot="toast-viewport"] .dropdown-glass)::before{content:"[ NOTIFICATION ]" !important;display:block !important;position:absolute !important;top:-8px;left:10px;padding:0 6px;background:#050911;color:var(--ac2);font:600 10px/16px var(--hud-display);letter-spacing:.18em;white-space:nowrap;pointer-events:none;z-index:1}
